"""Actual first permission publication plus existing full owner/statistics regressions.

Caller snapshot/table/syscall fixtures; actual frame compiler and complete
four-state transaction execute. Does not collect Java snapshots or expose RPCs.
"""
import argparse,hashlib,json,os,re,shutil,subprocess
from pathlib import Path
p=argparse.ArgumentParser(description=__doc__)
for n in ['source','reference-host','bootstrap-host','output']:p.add_argument('--'+n,type=Path,required=True)
a=p.parse_args();S=a.source.resolve();R=a.reference_host.resolve();H=a.bootstrap_host.resolve();O=a.output.resolve();assert not O.exists();O.mkdir(parents=True);sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
r=json.loads((R/'report.json').read_text());assert r['passed'] and r['passed_cases']==1537 and sha(R/'test.cpp')==r['inputs_sha256'][str(R/'test.cpp')]
b=json.loads((H/'report.json').read_text());assert b['passed'] and b['actual_A17_conversion_comparisons']==2048
for name in ['Gta3xlwifiPermissionBootstrap.cpp','Gta3xlwifiPermissionBootstrap.h','Gta3xlwifiUidPermissionState.cpp','Gta3xlwifiUidPermissionState.h']:
 hashes=[v for k,v in b['inputs_sha256'].items() if Path(k).name==name];assert hashes==[sha(S/name)]
shutil.copyfile(R/'IptablesRestoreController.h',O/'IptablesRestoreController.h');code=(R/'test.cpp').read_text().replace('int main(){','static int owner_api_regression_main(){',1)
code+=r'''
using Bootstrap=android::net::gta3xlwifi::PermissionBootstrap;
static Bootstrap::Snapshot completeFrame(bool loop=true){Bootstrap::Snapshot f;f.users={0};f.knownUids={10001,10002};f.observed={{0,1023},{1000,1023},{10001,4}};f.loopbackPermissionEnabled=loop;return f;}
static P::State initialPolicy(){auto s=desired();s.permissions=android::net::gta3xlwifi::UidPermissionState{};return s;}
int main(){
 assert(owner_api_regression_main()==0);unsigned before=cases,points=0;
 resetApi();{AccountingCombined k;P p(k);C(p.publishInitialPermissions(initialPolicy(),completeFrame())==-ENOTCONN&&opens==0);C(p.start()==0);auto count=ioCount;C(p.publishInitialPermissions(initialPolicy(),completeFrame())==-EOPNOTSUPP&&ioCount==count&&held);}
 for(bool loop:{false,true}){resetApi();AccountingCombined k;P p(k);C(p.startWithAccounting(accountingProgram)==0&&held);auto count=ioCount;auto partial=completeFrame(loop);partial.observed.erase(partial.observed.begin());C(p.publishInitialPermissions(initialPolicy(),partial)==-EPROTO&&ioCount==count&&held&&files.size()==1);P::State out;uint64_t g=77;C(p.snapshot(&out,&g)==-EAGAIN&&g==77);ioCount=0;C(p.publishInitialPermissions(initialPolicy(),completeFrame(loop))==0&&!held&&opens==1);points=ioCount;C(p.snapshot(&out,&g)==0&&g==1&&out.policy.dataSaver()==initialPolicy().policy.dataSaver());uint32_t mask=777;C(!out.permissions.get(10001,&mask)&&mask==0);C(!out.permissions.get(10002,&mask)&&mask==4);C(!out.permissions.get(0,&mask)&&mask==(loop?123u:3u));C(!out.permissions.get(1000,&mask)&&mask==(loop?123u:3u));count=ioCount;C(p.publishInitialPermissions(initialPolicy(),completeFrame())==-EALREADY&&ioCount==count&&!held);C(p.setDataSaver(false)==0&&!held);NetpolicyLease::PacketState stats;C(p.readPacketState(&stats)==0&&stats.activeEpoch==1&&!held);}
 C(points==114);
 for(unsigned error=0;error<5;error++){resetApi();AccountingCombined k;P p(k);C(p.startWithAccounting(accountingProgram)==0);auto frame=completeFrame();auto policy=initialPolicy();int expected=-EINVAL;switch(error){case 0:policy.permissions.set(10001,4);break;case 1:frame.observed.push_back({10001,4});break;case 2:frame.knownUids.push_back(-1);break;case 3:frame.knownUids.push_back(110001);expected=-EPROTO;break;case 4:frame.observed[0].bits=1022;expected=-EPROTO;break;}auto count=ioCount;C(p.publishInitialPermissions(policy,frame)==expected&&ioCount==count&&held&&files.size()==1);P::State out;uint64_t g=77;C(p.snapshot(&out,&g)==-EAGAIN&&g==77);C(p.publishInitialPermissions(initialPolicy(),completeFrame())==0&&!held&&opens==1);}
 for(bool after:{false,true})for(unsigned point=1;point<=points;point++){resetApi();AccountingCombined k;P p(k);C(p.startWithAccounting(accountingProgram)==0);ioCount=0;ioFault=point;ioAfter=after;C(p.publishInitialPermissions(initialPolicy(),completeFrame())<0&&held&&files.empty());P::State out;uint64_t g=77;C(p.snapshot(&out,&g)==-EAGAIN&&g==77);NetpolicyLease::PacketState stats;C(p.readPacketState(&stats)==-EAGAIN);C(p.publishInitialPermissions(initialPolicy(),completeFrame())==-ENOTCONN);}
 resetApi();{AccountingCombined k;P p(k);C(p.startWithAccounting(accountingProgram)==0);auto frame=completeFrame();frame.users={0,10};frame.knownUids.push_back(1010001);frame.observed.insert(frame.observed.end(),{{1000000,1023},{1001000,1023},{1010001,4}});C(p.publishInitialPermissions(initialPolicy(),frame)==0);P::State out;uint64_t g;uint32_t mask;C(!p.snapshot(&out,&g)&&!out.permissions.get(1010001,&mask)&&mask==0);}
 C(files.empty()&&held);printf("bootstrap_owner_cases=%u total_cases=%u publication_fault_points=%u\n",cases-before,cases,points);return 0;
}
''';(O/'test.cpp').write_text(code);names=['Gta3xlwifiNetpolicyLease','Gta3xlwifiCheckedUidChains','Gta3xlwifiUidPolicy','Gta3xlwifiUidChainProgram','Gta3xlwifiOrdinaryDispatch','Gta3xlwifiSocketRoots','Gta3xlwifiIngressPolicy','Gta3xlwifiMeteredChainProgram','Gta3xlwifiMeteredRoots','Gta3xlwifiUidPermissionState','Gta3xlwifiLocalNetworkState','Gta3xlwifiSocketPolicyProjection','Gta3xlwifiAccountingRoots','Gta3xlwifiPermissionBootstrap'];sources=[S/(n+'.cpp') for n in names];cmd=['c++','-std=c++20','-Wall','-Wextra','-Werror','-g','-O1','-fsanitize=undefined','-fno-sanitize-recover=all','-pthread','-I'+str(S),'-I'+str(O),*map(str,sources),str(O/'test.cpp'),'-o',str(O/'test')]+['-Wl,--wrap='+n for n in ['open','close','read','__read_chk','fstat','fstatfs','ioctl']]
x=subprocess.run(cmd,capture_output=True,text=True);(O/'compile.log').write_text(x.stdout+x.stderr);assert x.returncode==0,x.stderr
x=subprocess.run([str(O/'test')],capture_output=True,text=True,timeout=120,env={**os.environ,'UBSAN_OPTIONS':'halt_on_error=1'});(O/'test.log').write_text(x.stdout+x.stderr);assert x.returncode==0 and not x.stderr,(x.returncode,x.stdout,x.stderr);match=re.fullmatch(r'passed_cases=1251 start_fault_points=74 replace_fault_points=114\nowner_api_cases=286 total_cases=1537\nbootstrap_owner_cases=(\d+) total_cases=(\d+) publication_fault_points=114\n',x.stdout);assert match and int(match[1])>=1000
paths=[Path(__file__),R/'report.json',R/'test.cpp',H/'report.json',O/'test.cpp',O/'IptablesRestoreController.h',S/'projection-guards.inc',*sources,*[p.with_suffix('.h') for p in sources],*[p for p in (S/'linux/netfilter').glob('*.h')]];(O/'report.json').write_text(json.dumps({'passed':True,'scope':__doc__,'passed_cases':int(match[2]),'bootstrap_owner_cases':int(match[1]),'publication_fault_points':114,'one_lease_four_state_publication':True,'hard_no_firewall_after_first_image_set':True,'complete_frame_required_before_first_publication':True,'primary_conversion_report_sha256':sha(H/'report.json'),'inputs_sha256':{str(p):sha(p) for p in paths},'command':cmd,'stderr':x.stderr,'hardware_tested':False,'flash_ready':False},indent=2)+'\n');print(x.stdout.strip())
